class OutputValidator:
    def __init__(self):
        self.suspicious_patterns = [\
            r'SYSTEM\s*[:]\s*You\s+are',     # System prompt leakage\
            r'API[_\s]KEY[:=]\s*\w+',        # API key exposure\
            r'instructions?[:]\s*\d+\.',     # Numbered instructions\
